class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    stored_payload = @packer ? @packer.dump(payload) : payload
    @store[key] = { payload: stored_payload, stale: stale }
  end

  def read(key)
    entry = @store[key]
    return nil unless entry

    payload = entry[:payload]
    @packer ? @packer.load(payload) : payload
  end

  def sweep
    @store.delete_if { |_key, entry| entry[:stale] }
  end
end
